INNER JOIN `mod_customnpcs_bs_content` owner ON owner.`kind`='gameobject' AND owner.`entry`=g.`id` AND owner.`chapter`=2
WHERE g.`Comment` LIKE 'BS-C02:%' AND s.`spawn_key` IS NULL;
